def aspect_hint(text):
    """ملاحظة إنجليزية بتحدد اتجاه الصورة من كلام المستخدم (أو فاضية)."""
    low = (text or "").lower()
    for pat, hint in _ASPECT_HINTS:
        if re.search(pat, low):
            return hint
    return ""


