def run_ryn_mix_quality_suite():
    results = []
    passed_all = True
    for task in RYN_MIX_BENCHMARKS:
        tid = task["id"]
        items = [("task_" + tid, task["lang"], task["code"])]
        ver = run_verification_suite(items, orig_items=items, question=task["question"])
        checks_ok = True
        details = []
        if tid == "bug_fix":
            has_mutable_warn = any("قابل للتعديل" in w for w in ver["warnings"])
            inv = build_fallback_investigation(items, ver, task["question"])
            has_inv = len(inv.get("hypotheses") or []) >= 1 and bool(inv.get("confirmed_root_cause"))
            checks_ok = has_mutable_warn and has_inv and ver["all_passed"]
            details.append("كشف المعامل الافتراضي القابل للتعديل + توليد فرضيات السبب الجذري (Investigate): " + ("نجح ✅" if checks_ok else "فشل ❌"))
        elif tid == "feature_add":
            broken_code = "```python\ndef apply_discount(items, percent):\n    return 0\n\ndef helper_untouched(x):\n    return x * 999\n```"
            diff_w = check_diff_safety(items, broken_code, task["question"])
            scope_w = check_scope_lock(items, broken_code, "عدّل دالة calc_total فقط")
            caught_del = any("calc_total" in w for w in diff_w)
            caught_scope = any("helper_untouched" in w for w in scope_w)
            checks_ok = caught_del and caught_scope
            details.append("منع حذف الدوال القديمة + قفل النطاق (Scope Lock / Freeze): " + ("نجح ✅" if checks_ok else "فشل ❌"))
        elif tid == "ui_review":
            ui = ver["ui_audit"]
            caught_vp = any("viewport" in x for x in ui["objective_issues"])
            caught_btn = any("button" in x for x in ui["objective_issues"])
            caught_fetch = any("fetch" in x for x in ui["objective_issues"])
            checks_ok = caught_vp and caught_btn and caught_fetch
            details.append("كشف نواقص viewport والزر الفارغ وfetch غير المحمية: " + ("نجح ✅" if checks_ok else "فشل ❌"))
        elif tid == "security_audit":
            sec = ver["security_findings"]
            probs = " ".join(s["problem"] for s in sec)
            redacted = redact_secrets(task["code"])
            cheated_code = "```python\ndef find_user(db, username):\n    try:\n        return []\n    except Exception:\n        pass\n```"
            gate_w = check_gate_integrity(items, cheated_code)
            caught_gate = any("RH-1" in w for w in gate_w) and any("RH-16" in w for w in gate_w)
            caught_sec = ("SQL" in probs) and ("Command Injection" in probs or "shell=True" in probs) and ("[REDACTED_" in redacted) and caught_gate
            checks_ok = caught_sec
            details.append("كشف حقن SQL والأوامر وحجب المفتاح + منع تخفيف الفحوصات (Gate Integrity): " + ("نجح ✅" if caught_sec else "فشل ❌"))

        rep = ensure_ryn_report_template(
            "", task["question"], ["task_" + tid], ["task_" + tid], ver, []
        )
        template_ok = all(s in rep for s in _REPORT_SECTIONS) and rep.startswith("📌 **الحالة:")
        checks_ok = checks_ok and template_ok
        details.append("سطر الحالة بأول التقرير + التزام القالب السباعي: " + ("نجح ✅" if template_ok else "فشل ❌"))
        passed_all = passed_all and checks_ok
        results.append({
            "id": tid,
            "title": task["title"],
            "passed": checks_ok,
            "details": details,
        })
    selftest_res = None
    if S is not None and G is not None:
        try:
            gold_check = S.score_answer(S.GOLD_ANSWER)
            cl_check = G.closed_loop(S.ORIGINAL, lambda _p: S.GOLD_ANSWER, max_rounds=3, user_text=S.TEST_PROMPT)
            rep_check = G.finalize_report(
                "تمت المراجعة الأمنية.",
                cl_check["before"], cl_check["after"], cl_check["gate"],
                G.detect_injection(S.TEST_PROMPT)
            )
            full_check = rep_check + "\n\n```python\n" + cl_check["code"] + "\n```"
            selftest_res = S.score_answer(full_check)
            st_passed = selftest_res["score"] >= 16.0 and gold_check["score"] == 18.0
            passed_all = passed_all and st_passed
            results.append({
                "id": "security_18_benchmark",
                "title": "الاختبار الأمني الشامل (18/18 — ryn_guard + ryn_selftest)",
                "passed": st_passed,
                "details": [
                    "المرجع الذهبي (Gold Reference): %.2f / 18 ✅" % gold_check["score"],
                    "الحلقة المغلقة + بوابة التغيير + التقرير المحسوب: %.2f / 18 %s" % (selftest_res["score"], "✅" if st_passed else "❌"),
                ],
            })
        except Exception as e_st:
            passed_all = False
            results.append({
                "id": "security_18_benchmark",
                "title": "الاختبار الأمني الشامل (18/18 — ryn_guard + ryn_selftest)",
                "passed": False,
                "details": ["فشل تشغيل الاختبار الذاتي: %s" % str(e_st)[:120]],
            })
    return {
        "passed_all": passed_all,
        "total": len(results),
        "passed_count": sum(1 for r in results if r["passed"]),
        "tasks": results,
        "selftest_18": selftest_res,
        "model_rankings": {
            "writers": get_ranked_writers({k: True for k in _DEFAULT_WRITER_ORDER}),
            "reviewers": get_ranked_reviewers({k: True for k in _DEFAULT_REV1_ORDER}),
            "stats": MODEL_PERF_STATS,
        },
    }


def ryn_selftest_run(b_mod=None, members=None, live=False):
    """4) الاختبار الذاتي (18/18) كبوابة نشر وتقييم للموديلات."""
    import ryn_selftest as _S
    if not live or b_mod is None or not members:
        cl = G.closed_loop(_S.ORIGINAL, lambda _p: _S.GOLD_ANSWER, max_rounds=3, user_text=_S.TEST_PROMPT)
        rep = G.finalize_report(
            "تمت المراجعة الأمنية.",
            cl["before"], cl["after"], cl["gate"],
            G.detect_injection(_S.TEST_PROMPT)
        )
        ans = rep + "\n\n```python\n" + cl["code"] + "\n```"
        res = _S.score_answer(ans)
        res["passed"] = res["score"] >= 16.0
        log.info("Ryn selftest %.2f / 18", res["score"])
        return res
    T = b_mod.types
    contents = [T.Content(role="user", parts=[T.Part(text=_S.TEST_PROMPT)])]
    out = mix_answer(b_mod, contents, members, code=True, fix=True)
    text = out[0] if isinstance(out, tuple) else out
    res = _S.score_answer(text)
    res["passed"] = res["score"] >= 16.0
    log.info("Ryn selftest %.2f / 18", res["score"])
    return res


