def english_prompt(b, text, is_edit=False, has_ref_image=False):
    """يبني وصف الصورة الإنجليزي الاحترافي مع دمج قواعد الواقعية الفوتوغرافية المناسبة لطلب المستخدم."""
    raw = (text or "").strip()
    directives = select_realism_directives(raw, is_edit=is_edit, has_ref_image=has_ref_image)
    sys_inst = IMG_EDIT_SYS if (is_edit or has_ref_image) else IMG_SYS
    user_msg = raw
    if directives:
        user_msg = (
            "USER REQUEST:\n" + raw
            + "\n\nSCENE REALISM DIRECTIVES TO INTEGRATE NATURALLY:\n" + directives
        )
    try:
        T = b.types
        out = b.ask_gemini([T.Content(role="user", parts=[T.Part(text=user_msg)])], deep=False, system=sys_inst)
        cleaned = strip_ai_buzzwords((out or "").strip().strip('"'))
        if cleaned and len(cleaned) >= 20:
            return cleaned[:1800]
    except Exception as e:
        log.warning("english_prompt fallback: %s", str(e)[:120])
    # احتياط في حال تعذر استدعاء الموديل النصي: ندمج النص مع خلاصة الواقعية مباشرة
    fallback_base = strip_ai_buzzwords(raw)
    if directives and not _NON_PHOTO_STYLE_RE.search(raw):
        short_realism = (
            "RAW candid photograph shot on 35mm lens, single unified key light with accurate contact shadows and soft shadow penumbra, "
            "natural skin texture with visible pores, fine peach fuzz, catchlights in eyes, subtle facial asymmetry, accurate 5-finger hands, "
            "natural fabric weave and folds, authentic lived-in environment with accurate optical refraction and perspective, "
            "natural depth of field with soft bokeh, subtle film grain, muted natural colors, zero plastic or waxy shine."
        )
        return (fallback_base + ", " + short_realism)[:1800]
    return fallback_base[:1800]


def sniff_image(data):
    """نوع الصورة من أول بايتات الملف (JPEG/PNG/WEBP/HEIC)."""
    if data[:3] == b"\xff\xd8\xff":
        return "image/jpeg"
    if data[:8] == b"\x89PNG\r\n\x1a\n":
        return "image/png"
    if data[:4] == b"RIFF" and data[8:12] == b"WEBP":
        return "image/webp"
    if data[4:8] == b"ftyp" and data[8:12] in (b"heic", b"heix", b"heim", b"heis", b"mif1", b"msf1"):
        return "image/heic"
    return None


def img_models():
    """سلسلة موديلات رسم Gemini بالترتيب (الأقوى أول، قابل للتخصيص بـ GEMINI_IMAGE_MODEL)."""
    seen = []
    for m in [os.environ.get("GEMINI_IMAGE_MODEL", "").strip(),
              "gemini-3.1-flash-image",
              "gemini-3.1-flash-lite-image",
              "gemini-3-pro-image",
              "gemini-3.1-flash-image-preview",
              "gemini-2.5-flash-image",
              "gemini-3-pro-image-preview"]:
        if m and m not in seen:
            seen.append(m)
    return seen


def _extract_ref_image_parts(T, ctx, last_img_b64=None, prompt_text=""):
    """استخراج أجزاء الصورة المرجعية (من المرفقات أو من آخر صورة مولّدة، مع دعم دمج صور متعددة وتوسيع الحواف)."""
    ref_parts = []
    if ctx and ctx.get("image"):
        for p in (ctx.get("parts") or []):
            if getattr(p, "inline_data", None) is not None:
                ref_parts.append(p)
    wants_merge = bool(re.search(r"(?i)(ادمج|دمج|ركّ?ب\s+الصورتين|اجمع\s+الصورتين|\b(?:merge|blend|combine)\b)", prompt_text or ""))
    if (not ref_parts or (wants_merge and len(ref_parts) == 1)) and last_img_b64 and isinstance(last_img_b64, str) and last_img_b64.startswith("data:image/"):
        try:
            header, b64data = last_img_b64.split(",", 1)
            mime = header.split(";")[0].replace("data:", "") or "image/jpeg"
            raw_bytes = base64.b64decode(b64data)
            ref_parts.append(T.Part.from_bytes(data=raw_bytes, mime_type=mime))
        except Exception:
            _ = None
    # إذا كان الطلب توسيع صورة (Outpainting) نوسّع حواف الصورة المرجعية تلقائياً
    if ref_parts and re.search(r"(?i)(وسّ?ع\s+الصورة|توسيع\s+الصورة|خارج\s+حدودها|\b(?:outpaint|outpainting|expand\s+image|uncrop)\b)", prompt_text or ""):
        try:
            from image_processing.preprocessing import expand_canvas_for_outpaint
            p0 = ref_parts[0]
            inl = getattr(p0, "inline_data", None)
            raw_b = getattr(inl, "data", None) if inl else None
            if isinstance(raw_b, (bytes, bytearray)) and len(raw_b) > 64:
                expanded_b = expand_canvas_for_outpaint(bytes(raw_b))
                ref_parts[0] = T.Part.from_bytes(data=expanded_b, mime_type="image/png")
        except Exception:
            _ = None
    return ref_parts


def _decode_inline_image_bytes(raw_data):
    if not raw_data:
        return b""
    if isinstance(raw_data, (bytes, bytearray)):
        return bytes(raw_data)
    if isinstance(raw_data, str):
        try:
            return base64.b64decode(raw_data, validate=True)
        except Exception:
            try:
                return base64.b64decode(raw_data)
            except Exception:
                return raw_data.encode("utf-8")
    return b""


def _try_gemini_image(b, model, full, ref_parts=None):
    """يدعم توليد صورة جديدة أو تعديل صورة مرفقة (Image-to-Image Editing) عبر Gemini مع إعادة المحاولة لصيغ Modalities."""
    T = b.types
    client = b.client
    last = None
    if not ref_parts:
        try:
            if os.environ.get("IMAGE_USE_INTERACTIONS", "0") != "1":
                raise RuntimeError("interactions متوقفة")
            it = client.interactions.create(model=model, input=full)
            oi = getattr(it, "output_image", None)
            if oi is not None:
                data = _decode_inline_image_bytes(getattr(oi, "data", None))
                if data:
                    return data, (getattr(oi, "mime_type", None) or "image/png")
        except Exception as e:
            last = e

    req_contents = ([T.Content(role="user", parts=list(ref_parts) + [T.Part(text=full)])]
                    if ref_parts else full)

    for modalities in (["TEXT", "IMAGE"], ["IMAGE"]):
        cfg = None
        try:
            cfg = T.GenerateContentConfig(response_modalities=modalities,
                                          http_options=T.HttpOptions(timeout=55000))
        except Exception:
            try:
                cfg = T.GenerateContentConfig(response_modalities=modalities)
            except Exception:
                cfg = None
        try:
            resp = client.models.generate_content(model=model, contents=req_contents, config=cfg)
        except Exception as e:
            last = e
            code = getattr(e, "code", None)
            if code in (401, 403, 429):
                raise
            continue

        gen = getattr(resp, "generated_images", None) or []
        if gen:
            g = gen[0]
            im = getattr(g, "image", None) or g
            data = _decode_inline_image_bytes(getattr(im, "image_bytes", None) or getattr(im, "_image_bytes", None))
            if not data:
                pil = getattr(im, "_pil_image", None)
                if pil is not None:
                    buf = io.BytesIO()
                    pil.save(buf, format="PNG")
                    data = buf.getvalue()
            if data:
                return data, (getattr(im, "mime_type", None) or "image/png")

        for c in (getattr(resp, "candidates", None) or []):
            content_obj = getattr(c, "content", None)
            for p in (getattr(content_obj, "parts", None) or []):
                inline = getattr(p, "inline_data", None)
                if inline is not None:
                    data = _decode_inline_image_bytes(getattr(inline, "data", None))
                    if data:
                        return data, (getattr(inline, "mime_type", None) or "image/png")
    if last is not None:
        raise last
    raise RuntimeError("الرد ما فيه صورة")


def gemini_image(b, full, ref_parts=None):
    """بيجرّب كل موديلات الرسم/التعديل بالترتيب وبيرجّع (data, mime, model)."""
    last = None
    t0 = time.time()
    for model in img_models():
        if time.time() - t0 > 110:
            log.warning("الرسم: خلصت المهلة الكلية، وقفت التجربة")
            break
        try:
            log.info("الرسم/التعديل: بجرّب %s (مرفق صورة=%s)", model, bool(ref_parts))
            data, mime = _try_gemini_image(b, model, full, ref_parts=ref_parts)
            log.info("الرسم/التعديل: %s خلص بـ %.0f ثانية", model, time.time() - t0)
            if data:
                return data, mime, model
        except Exception as e:
            last = e
            code = getattr(e, "code", None)
            if code in (401, 403, 429):
                raise
            log.warning("موديل الرسم %s فشل: %s", model, e)
    if last is not None:
        raise last
    raise RuntimeError("ما في موديل رسم متاح")


class _ImgError(Exception):
    """خطأ رسم برسالة عربية جاهزة للعرض للمستخدم."""


def img_label(model):
    """اسم قصير ومفهوم لموديل الرسم."""
    m = (model or "").lower()
    if "together" in m:
        return "Together FLUX"
    if "pro-image" in m:
        return "Gemini Image Pro"
    if "instruct-pix2pix" in m or "pix2pix" in m:
        return "InstructPix2Pix (timbrooks/instruct-pix2pix)"
    if "flash-image" in m:
        return "Gemini Image"
    if "klein" in m:
        return "FLUX.2 klein"
    if "flux-2" in m:
        return "FLUX.2"
    if "lucid" in m:
        return "Lucid Origin"
    if "schnell" in m:
        return "FLUX.1 schnell"
    return (model or "").split("/")[-1]


_CHAT_NAMES = (("ryn mix", "Ryn mix"), ("gpt-oss", "GPT-OSS"), ("qwen", "Qwen"), ("deepseek", "DeepSeek"),
               ("kimi", "Kimi"), ("moonshot", "Kimi"), ("llama", "Llama"), ("gemma", "Gemma"),
               ("mistral", "Mistral"), ("codestral", "Codestral"), ("glm", "GLM"), ("nemotron", "Nemotron"),
               ("claude", "Claude"), ("gemini", "Gemini"))


def short_name(note, fallback="Gemini"):
    """بيحوّل ملاحظة البوت الطويلة لاسم الموديل بس."""
    n = (note or "").lower()
    if "جاوب gemini" in n or "استخدمت gemini" in n:
        return "Gemini"
    for k, v in _CHAT_NAMES:
        if k in n:
            return v
    return fallback


def _img_result(data, model_name, en):
    mime = sniff_image(data) or "image/jpeg"
    log.info("الرسم: %s · الوصف: %s", model_name, en[:200])
    return {"status": "done", "text": "تفضّل الصورة 🎨",
            "image": "data:%s;base64,%s" % (mime, base64.b64encode(data).decode()),
            "note": img_label(model_name)}


def together_image(b, full, en):
    """احتياط اختياري عبر Together AI (لازم TOGETHER_API_KEY)."""
    key = os.environ.get("TOGETHER_API_KEY", "").strip()
    model = os.environ.get("TOGETHER_IMAGE_MODEL", "black-forest-labs/FLUX.1-schnell-Free").strip()
    try:
        r = b.requests.post("https://api.together.xyz/v1/images/generations",
                            headers={"Authorization": "Bearer " + key, "Content-Type": "application/json"},
                            json={"model": model, "prompt": full[:1500], "width": 1024, "height": 1024,
                                  "steps": 4, "n": 1, "response_format": "b64_json"}, timeout=90)
    except Exception as e:
        raise _ImgError("Together: " + str(e)[:80])
    if r.status_code != 200:
        raise _ImgError("Together: كود %s" % r.status_code)
    try:
        data = base64.b64decode(r.json()["data"][0]["b64_json"])
    except Exception:
        raise _ImgError("Together: رد بدون صورة")
    return _img_result(data, "%s (Together)" % model.split("/")[-1], en)


def flux_image(b, full, en):
    """احتياط مجاني عبر Cloudflare Workers AI: Lucid Origin (واقعي) ثم FLUX.1 schnell."""
    acc = os.environ["CLOUDFLARE_ACCOUNT_ID"].strip()
    tok = os.environ["CLOUDFLARE_API_TOKEN"].strip()
    models = []
    for m in [os.environ.get("CLOUDFLARE_IMAGE_MODEL", "").strip(),
              "@cf/leonardo/lucid-origin",
              "@cf/black-forest-labs/flux-1-schnell",
              "@cf/black-forest-labs/flux-2-klein-4b"]:
        if m and m not in models:
            models.append(m)
    last_err = None
    for model in models:
        url = "https://api.cloudflare.com/client/v4/accounts/%s/ai/run/%s" % (acc, model)
        try:
            log.info("Cloudflare: بجرّب %s", model)
            if "flux-2" in model:   # عيلة FLUX.2 بتاخد multipart/form-data مو JSON
                r = b.requests.post(
                    url, headers={"Authorization": "Bearer " + tok},
                    files={"prompt": (None, full), "width": (None, "1024"), "height": (None, "1024")},
                    timeout=120)
            else:
                payload = {"prompt": full, "steps": 8} if "schnell" in model else \
                    {"prompt": full, "width": 1024, "height": 1024}
                r = b.requests.post(
                    url, headers={"Authorization": "Bearer " + tok, "Content-Type": "application/json"},
                    json=payload, timeout=90)
        except Exception as e:
            log.warning("Cloudflare %s: %s", model, e)
            last_err = _ImgError("ما قدرت أوصل لـ Cloudflare، جرّب تاني.")
            continue
        data = None
        ct = str((getattr(r, "headers", None) or {}).get("content-type", ""))
        if r.status_code == 200 and ct.startswith("image/"):
            data = r.content
        else:
            try:
                j = r.json()
            except ValueError:
                j = {}
            if r.status_code == 200 and (j.get("result") or {}).get("image"):
                data = base64.b64decode(j["result"]["image"])
            else:
                errs = "; ".join(str(e.get("message", e)) if isinstance(e, dict) else str(e)
                                 for e in (j.get("errors") or []))[:200]
                low = errs.lower()
                log.warning("Cloudflare %s فشل %s: %s", model, r.status_code, errs)
                if r.status_code in (401, 403):
                    raise _ImgError("🔑 مفتاح Cloudflare مو مقبول، تأكد من CLOUDFLARE_API_TOKEN.")
                if r.status_code == 429 or "limit" in low or "quota" in low or "neurons" in low:
                    raise _ImgError("⏳ خلصت حصة الرسم اليومية المجانية، جرّب بكرا.")
                if "nsfw" in low:
                    raise _ImgError("⛔ الوصف مرفوض (محتوى غير مناسب)، جرّب وصف تاني.")
                last_err = _ImgError("ما قدرت أرسم (%s). %s" % (r.status_code, errs))
                continue
        if not data:
            last_err = _ImgError("رد Cloudflare بدون صورة")
            continue
        mime = sniff_image(data) or "image/jpeg"
        short = model.split("/")[-1]
        return _img_result(data, model, en)
    raise last_err or _ImgError("ما قدرت أرسم هلق، جرّب تاني.")


def image_error(e):
    """رسالة عربية لطيفة حسب نوع خطأ الرسم."""
    if isinstance(e, _ImgError):
        return str(e)
    code = getattr(e, "code", None)
    s = str(e).lower()
    if code == 429 or "429" in s or "quota" in s or ("rate" in s and "limit" in s):
        return "⏳ خلصت حصة الرسم اليومية (الحد المجاني)، جرّب بكرا."
    if code in (401, 403):
        return "🔑 في مشكلة بمفتاح Google بالـ Environment Variables."
    if "nsfw" in s or "safety" in s or "recitation" in s or "blocked" in s:
        return "⛔ الوصف مرفوض (محتوى غير مناسب أو مخالف)، جرّب وصف تاني."
    return "ما قدرت أرسم هلق، جرّب تاني بعد شوي."


