    def run_image(job_id, prompt, day, u="main"):
        res = None
        try:
            T = b.types
            W = wid(u)
            ctx = b.get_doc(W)
            is_edit_req = bool(_IMG_EDIT_INTENT_RE.search(prompt))
            has_attached_img = bool(ctx and ctx.get("image"))
            mem_latest_uri = vbrain.memory.get_latest_image_uri(u) if vbrain is not None else last_generated_images.get(u)
            ref_parts = _extract_ref_image_parts(
                T, ctx, mem_latest_uri if is_edit_req else None, prompt_text=prompt
            )
            if is_cancelled(job_id):
                return
            if vbrain is not None:
                set_progress(job_id, "🧠 العقل البصري عم يحلل المشهد ويبني خطة التنفيذ...")
                provs = _build_provider_instances()
                avail_map = {k: p.is_ready() for k, p in provs.items()}
                def _ask_llm_for_prompt(user_msg, sys_inst):
                    if b.client:
                        try:
                            out = b.ask_gemini([T.Content(role="user", parts=[T.Part(text=user_msg)])], deep=False, system=sys_inst)
                            if out and len(out.strip()) >= 20:
                                return out
                        except Exception as _ge:
                            log.warning("Prompt LLM Gemini fallback to Groq: %s", str(_ge)[:100])
                    if hasattr(b, "_groq_ready") and b._groq_ready():
                        try:
                            g_backend = {**b.GROQ_CHAT_BACKEND, "system": sys_inst, "compact": False}
                            return b._call_backend(g_backend, [T.Content(role="user", parts=[T.Part(text=user_msg)])], False, False, models=b.groq_code_models())
                        except Exception as _gre:
                            log.warning("Prompt LLM Groq fallback failed: %s", str(_gre)[:100])
                    return ""

                def _ask_vision_id(r_parts, v_prompt):
                    if b.client:
                        try:
                            return b.ask_gemini([T.Content(role="user", parts=list(r_parts) + [T.Part(text=v_prompt)])], deep=False)
                        except Exception:
                            _ = None
                    return ""
                plan = vbrain.build_plan(
                    user_text=prompt,
                    user_id=u,
                    available_providers=avail_map,
                    preferred_provider=IMG_PROVIDER,
                    aspect_hint_str=aspect_hint(prompt),
                    ask_llm_fn=_ask_llm_for_prompt,
                    ask_vision_fn=_ask_vision_id if (b.client and ref_parts) else None,
                    ref_parts=ref_parts,
                )
                runners = {k: p.generate for k, p in provs.items() if p.is_ready()}
                if not runners and plan.intent != "revert":
                    raise _ImgError("الرسم مش مفعّل: بده GEMINI_API_KEY أو Cloudflare أو الاحتياط المجاني.")
                def _vision_critic_audit(gen_img_bytes, audit_prompt):
                    if b.client:
                        try:
                            img_part = T.Part.from_bytes(data=gen_img_bytes, mime_type="image/png")
                            v_out = b.ask_gemini([T.Content(role="user", parts=[img_part, T.Part(text=audit_prompt)])], deep=False)
                            if v_out:
                                return v_out
                        except Exception as _ve:
                            log.warning("Vision Critic Gemini fallback to Groq Vision: %s", str(_ve)[:100])
                    if hasattr(b, "_groq_ready") and b._groq_ready():
                        try:
                            b64_img = base64.b64encode(gen_img_bytes).decode("ascii")
                            g_key = b._env_key("GROQ_API_KEY")
                            for v_mdl in ("meta-llama/llama-4-scout-17b-16e-instruct", "meta-llama/llama-4-maverick-17b-128e-instruct"):
                                vr = b.requests.post(
                                    b.GROQ_BASE + "/chat/completions",
                                    headers={"Authorization": "Bearer " + g_key, "Content-Type": "application/json"},
                                    json={
                                        "model": v_mdl,
                                        "messages": [{
                                            "role": "user",
                                            "content": [
                                                {"type": "text", "text": audit_prompt},
                                                {"type": "image_url", "image_url": {"url": "data:image/png;base64," + b64_img}},
                                            ],
                                        }],
                                        "max_tokens": 220,
                                    },
                                    timeout=30,
                                )
                                if vr.status_code == 200:
                                    v_txt = ((vr.json().get("choices") or [{}])[0].get("message") or {}).get("content") or ""
                                    if v_txt.strip():
                                        return v_txt.strip()
                        except Exception as _gve:
                            log.warning("Vision Critic Groq failed: %s", str(_gve)[:100])
                    return "OK"

                exec_out = vbrain.execute_plan(
                    plan,
                    user_id=u,
                    provider_runners=runners,
                    ref_parts=ref_parts,
                    max_quality_retries=2,
                    progress_cb=lambda msg: set_progress(job_id, msg),
                    vision_audit_fn=_vision_critic_audit,
                )
                exec_out.pop("image_bytes", None)
                if exec_out.get("model"):
                    exec_out["note"] = img_label(exec_out["model"])
                res = exec_out
                if res.get("image"):
                    last_generated_images[u] = res["image"]
                    if has_attached_img:
                        b.doc_ctx.pop(W, None)
            else:
                # مسار احتياطي مباشر إذا لم تتوفر حزمة visual_brain
                is_edit_mode = bool(ref_parts)
                en = english_prompt(b, prompt, is_edit=is_edit_mode or is_edit_req, has_ref_image=is_edit_mode)
                ah = aspect_hint(prompt)
                full = (en + ((" " + ah) if ah else "")).strip()
                data, mime, model = gemini_image(b, full, ref_parts=ref_parts)
                res = _img_result(data, model, en)
                if res and res.get("image"):
                    last_generated_images[u] = res["image"]
        except (_ImgError, UnsupportedEditOperationError) as e:
            res = {"status": "error", "text": str(e)}
        except Exception as e:
            log.exception("web image error")
            res = {"status": "error", "text": image_error(e)}
        if res and res.get("status") == "done" and AIStack is not None:
            try:
                AIStack.get_quota_tracker().record_usage(u, "visual_brain", requests_delta=1, tokens_delta=1200)
            except Exception:
                _ = None
        if res and res.get("status") != "done":
            img_counts[day] = max(0, img_counts.get(day, 1) - 1)
            if vbrain is not None:
                vbrain.memory.decrement_daily_count(day)
        if res:
            finish(job_id, res)

    IMG_HARD_TIMEOUT = int(os.environ.get("IMAGE_TIMEOUT", "240"))

    def guarded_image(job_id, prompt, day, u="main"):
        """بيشغّل الرسم بخيط، وإذا علّق أكتر من المهلة بيسكّر الطلب بخطأ واضح."""
        t = threading.Thread(target=run_image, args=(job_id, prompt, day, u), daemon=True)
        t.start()
        t.join(IMG_HARD_TIMEOUT)
        if not t.is_alive():
            return
        with jlock:
            j = jobs.get(job_id)
            still = bool(j) and j.get("status") == "running"
        if still:
            log.error("الرسم علّق أكتر من %s ثانية، سكّرت الطلب %s", IMG_HARD_TIMEOUT, job_id)
            img_counts[day] = max(0, img_counts.get(day, 1) - 1)
            finish(job_id, {"status": "error",
                            "text": "⏳ الرسم تأخر كتير وانوقف، جرّب تاني أو بسّط الوصف."})

    @app.post("/api/image")
    def api_image():
        bad = guard()
        if bad:
            return bad
        if not image_ready():
            return jsonify(error="الرسم بده GEMINI_API_KEY أو إعداد Cloudflare (CLOUDFLARE_ACCOUNT_ID و CLOUDFLARE_API_TOKEN على Render)"), 503
        prompt = str((request.get_json(silent=True) or {}).get("prompt", "")).strip()[:1200]
        if not prompt:
            return jsonify(error="اكتب وصف الصورة أو التعديل المطلوب"), 400
        cur_u = uid()
        day = cur_u + "|" + time.strftime("%Y-%m-%d")   # الحصة لكل مستخدم لحاله
        now = time.time()
        with jlock:
            for k in [k for k, v in jobs.items() if now - v["ts"] > 900]:
                jobs.pop(k, None)
            if sum(1 for v in jobs.values() if v["status"] == "running" and v.get("uid") == cur_u) >= 2:
                return jsonify(error="في طلبين شغّالين، استنى لحظة"), 429
            cur_cnt = max(img_counts.get(day, 0), vbrain.memory.get_daily_count(day) if vbrain is not None else 0)
            if cur_cnt >= IMG_DAILY:
                return jsonify(error="وصلت الحد اليومي للصور (%d)، كمّل بكرا." % IMG_DAILY), 429
            img_counts[day] = cur_cnt + 1
            if vbrain is not None:
                vbrain.memory.increment_daily_count(day)
            job_id = uuid.uuid4().hex
            jobs[job_id] = {"status": "running", "ts": now, "uid": cur_u}
        threading.Thread(target=guarded_image, args=(job_id, prompt, day, cur_u), daemon=True).start()
        return jsonify(job=job_id)

